arguments.command:
node -e "
const fs=require('fs');
const html=fs.readFileSync('index.html','utf8');
const js=fs.readFileSync('app.js','utf8');
if(!/id=[\"']increment[\"']/.test(html)) throw new Error('missing #increment');
if(!/id=[\"']count[\"']/.test(html)) throw new Error('missing #count');
if(!/<span id=[\"']count[\"']>0<\/span>/.test(html)) throw new Error('#count not 0');
// simulate DOM
let text='0';
const el={get textContent(){return text;},set textContent(v){text=v;}};
const listeners={};
const button={addEventListener:(e,f)=>listeners[e]=f};
global.document={getElementById:id=>id==='increment'?button:el};
eval(js);
listeners.click();
if(text!=='1') throw new Error('count is '+text+' not 1');
console.log('OK: click changed #count from 0 to 1');
"

